insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-daytime-session-appends-handoff-s683','decision','A daytime code session appends a dated section to the newest handoff','S683 conductor, at Sam''s word to leave tonight''s name (SkyNuthatch, Session 683) for tonight: a daytime code session takes the next number with a daytime label and adds a dated section, ## Daytime session, <moniker> (S<N> daytime), <date>, to the newest handoff instead of writing a new number. kb/_build_session_spend.py reads that section''s own Spend line as session N daytime.',array['handoff','scheduled-sessions','checkpoint'],'proposed','docs/reference/scheduled_sessions.md; docs/session_683_handoff.md','SkyDipper (S683 daytime), the conductor',null,'SkyDipper (S683 daytime)',date '2026-11-18'),
('d-dependency-map-on-main-s683','decision','Merge rules: the dependency map rebuilt on main, at most three open PRs','Sam, Nov 18 about 1:10 PM PT, relayed by COBIx on #3358: no dependency-map rebuild inside PRs; one job on main rebuilds the map files after each merge (#3526, open). Also at most 3 open PRs (plus #3511 and dependabot), oldest finished first, one update from main right before its merge, no full rerun when input fingerprints match. Until #3526 lands, CI may flag the map: leave it.',array['merge-rules','dependency-map','repo-size','branch-policy'],'proposed','#3358; #3526; docs/reference/sam_rulings.md','Sam, relayed by COBIx on #3358',null,'SkyDipper (S683 daytime)',date '2026-11-18'),
('d-nightly-prs-exception-to-cap-s683','decision','Nightly PRs stay open through the night of Nov 18 as an exception to the cap','S683 conductor under Sam''s merge rules: nightly #3497, #3508, #3492 and #3500 stay open through the night run of 2026-11-18 as a stated exception to the three-open-PR cap, then the conductor parks what is left as issues (PR closed, branch kept), as it did for #3516, #3518, #3482 and #3293 (issues #3522 to #3525).',array['merge-rules','program-requirements-harvest'],'proposed','#3358; docs/session_683_handoff.md','SkyDipper (S683 daytime), the conductor',null,'SkyDipper (S683 daytime)',date '2026-11-18'),
('p-cer-procedures-left-side-by-side-stale-s683','pitfall','The CER procedures run left the Side by side views stale','S683 (#3520): main went red after CER procedures run 44350607385, because the run changed what the Side by side views read without rebuilding them. cer-procedures.yml now rebuilds the views; a failed rebuild holds the review queue back and ends the run red; the tests pick their fixtures by rule rather than a fixed title.',array['cer-procedures','ci','side-by-side'],'proposed','#3520','SkyDipper (S683 daytime), the conductor',null,'SkyDipper (S683 daytime)',date '2026-11-18'),
('p-workflow-workers-share-main-checkout-s683','pitfall','Inside a Workflow, worker worktree isolation was not honored','S683: agentType worker''s isolation: worktree was not honored inside a Workflow. Two workers shared the conductor''s checkout; one committed on the session branch, another checked out #3472''s old tree over it. The fix is an explicit worktree rule in every brief: name the path the agent creates off origin/main and stays in (.claude/skills/conductor-brief item 4).',array['conductor','workflow','worktree','agents'],'proposed','.claude/skills/conductor-brief/SKILL.md','SkyDipper (S683 daytime), the conductor',null,'SkyDipper (S683 daytime)',date '2026-11-18'),
('f-inactive-cards-double-resolve-s683','fact','The inactive course flag: 3,357 cards, and why Source 13 read 1,067','S683 (#3519): the inactive flag covers 3,357 cards; 1,119 are in the counted scope, 1,116 leave the counts and 3 a person reviewed stay. COBIx''s Source 13 read 1,067 because it resolved exhibit links through the alias chain twice; kb/coci_articulations.json is already current-era, so the builder reads links raw and refuses a file without its applied markers.',array['commons','course-flags','alias-chain'],'proposed','#3519; #3480 Source 13; kb/_flags.py','SkyDipper (S683 daytime), the conductor',null,'SkyDipper (S683 daytime)',date '2026-11-18'),
('d-rule-g-two-mapped-colleges-s683','decision','Rule G accepts a card only when two mapped colleges carry it','S683 conductor (#3513): rule G, last in kb/_ccr_confidence_score.py, accepts a card only when two mapped colleges carry it: 166 accepts with --fill-members, 105 without. Rule M (47 MUSI to MUSC moves, 5 keeps) and FPR (38 moves) are refused by kb/_ccr_confidence_apply.py until a re-mint under docs/coursecontrolnumber_remint.md (--worklist). W and D stay off.',array['commons','ccr','confidence-rules','rule-g'],'proposed','#3513; kb/_ccr_confidence_apply.py','SkyDipper (S683 daytime), the conductor',null,'SkyDipper (S683 daytime)',date '2026-11-18'),
('f-cr-exact-match-live-counts-s683','fact','CR exact match: live counts of Nov 18','S683 live read (#3518, parked as issue #3523): the CR inventory''s 29,995 rows are MAP only 3,334, an exact match 202, and a typographic or real difference 26,459. map_ace_catalog_cr holds 104,688 rows over 25,742 exhibits.',array['common-cr-reference','ace','cr-exact-match'],'proposed','#3518; #3523','SkyDipper (S683 daytime), the conductor',null,'SkyDipper (S683 daytime)',date '2026-11-18'),
('d-cobix-watcher-s683','decision','Sessions watch for COBIx''s comments themselves','Sam, Nov 18 about 1:17 PM PT, relayed by COBIx on #3358: watch for COBIx comments yourself, so Sam does not have to relay them. scripts/cobix_watch.sh polls every 5 minutes with two gh api -X GET search/issues searches (threads cobi-cto commented on, changed since the last poll) and a saved last-seen file; every handoff opens by restarting it (checkpoint step 8).',array['cobix','watcher','handoff','collaboration'],'proposed','#3358; scripts/cobix_watch.sh; tests/cobix_watch_test.py','Sam, relayed by COBIx on #3358',null,'SkyDipper (S683 daytime)',date '2026-11-18'),
('f-same-subject-list-s683','fact','Exhibits Review: a Same subject list under Related titles','Sam''s ask, Nov 18 about 3:16 PM PT, in the S683 daytime session: a Same subject list under an Exhibits Review card''s Related titles. #3528 (open) adds it; on the Las Positas card CDEV 100 shows sixth, with 87 colleges. It goes live once the next build rewrites kb/exhibits_review.json.',array['cer-procedures','exhibits-review','related-titles'],'proposed','#3528; docs/reference/sam_rulings.md','SkyDipper (S683 daytime), the conductor',null,'SkyDipper (S683 daytime)',date '2026-11-18')
on conflict (slug) do nothing;

